$ErrorActionPreference='Stop';Import-Module (Join-Path $PSScriptRoot 'Repato.MayaQaWorkflow.psm1') -Force -WarningAction SilentlyContinue;Import-Module (Join-Path $PSScriptRoot 'Repato.AgentOrchestration.psm1') -Force -WarningAction SilentlyContinue
$runs=[IO.Path]::GetFullPath((Join-Path $PSScriptRoot '..\QA\TestRuns'));$fixture=[IO.Path]::GetFullPath((Join-Path $PSScriptRoot '..\QA\Fixtures\CreatePlanViewsEmpty.rvt'));$candidate=[IO.Path]::GetFullPath((Join-Path $PSScriptRoot '..\DeploymentCandidates'));$made=[Collections.Generic.List[string]]::new()
function New-Context([string]$name){$s=Join-Path ([IO.Path]::GetTempPath()) ('prepared-clean-'+[guid]::NewGuid().ToString('N'));New-Item -ItemType Directory $s -Force|Out-Null;$id='task-'+[guid]::NewGuid().ToString('N');$wf='workflow-'+[guid]::NewGuid().ToString('N');$run=[guid]::NewGuid().ToString('N');$att=[guid]::NewGuid().ToString('N');New-RepatoTask $s $id 'Maya QA request' 'Create Plan Views' 'qa/maya-qa-workflow' 'maya'|Out-Null;$rt=Join-Path $runs ($wf+'-'+$run+'-'+$name);New-Item -ItemType Directory $rt -Force|Out-Null;Copy-Item $fixture (Join-Path $rt 'model.rvt');Set-Content (Join-Path $rt 'model.rvt.fixture.json') '{}';$a=[pscustomobject]@{TaskId=$id;WorkflowId=$wf;RunId=$run;AttemptId=$att;RuntimeRoot=$rt;RequestExpiresUtc=([DateTimeOffset]::UtcNow.AddMinutes(30).ToString('O'));Stage='prepared';Success=$false;RequestPath=$null};$p=[pscustomobject]@{TaskId=$id;WorkflowId=$wf;RunId=$run;AttemptId=$att;ModelPath=(Join-Path $rt 'model.rvt');SidecarPath=(Join-Path $rt 'model.rvt.fixture.json');HandoffId='handoff-'+$att};Invoke-RepatoStoreMutation $s {param($d,$x)$t=Find-RepatoTask $d $id;$t|Add-Member NoteProperty mayaTaraAttempt $a -Force;$t|Add-Member NoteProperty mayaTaraQaPacket $p -Force;$t}|Out-Null;$made.Add($rt);[pscustomobject]@{Store=$s;TaskId=$id;WorkflowId=$wf;RunId=$run;AttemptId=$att;Runtime=$rt}
}
function Add-UnrelatedAttemptShapes($c){foreach($id in 'unrelated-absent','unrelated-null','unrelated-legacy','unrelated-complete'){New-RepatoTask $c.Store $id 'Unrelated' 'Unrelated' 'qa/test' 'maya'|Out-Null};$d=Read-RepatoTaskStore $c.Store;$nullTask=Find-RepatoTask $d 'unrelated-null';$nullTask|Add-Member NoteProperty mayaTaraAttempt $null -Force;$legacyTask=Find-RepatoTask $d 'unrelated-legacy';$legacyTask|Add-Member NoteProperty mayaTaraAttempt ([pscustomobject]@{TaskId='unrelated-legacy';AttemptId='legacy'}) -Force;$otherTask=Find-RepatoTask $d 'unrelated-complete';$otherTask|Add-Member NoteProperty mayaTaraAttempt ([pscustomobject]@{RuntimeRoot=(Join-Path $runs 'unrelated-runtime')}) -Force;Write-RepatoJsonAtomic (Join-Path $c.Store 'tasks.json') $d}
function Reject($c,[scriptblock]$change,[string]$name){&$change $c;$exists=Test-Path $c.Runtime;$bad=$false;try{Complete-MayaQaPreparedAttemptCleanup -StoreRoot $c.Store -TaskId $c.TaskId -WorkflowId $c.WorkflowId -RunId $c.RunId -AttemptId $c.AttemptId|Out-Null}catch{$bad=$true};if(!$bad -or ($exists -and !(Test-Path $c.Runtime))){throw "Unsafe case failed: $name"}}
$p=New-Context positive;try{Add-UnrelatedAttemptShapes $p;$r=Complete-MayaQaPreparedAttemptCleanup -StoreRoot $p.Store -TaskId $p.TaskId -WorkflowId $p.WorkflowId -RunId $p.RunId -AttemptId $p.AttemptId;if($r.Mode -ne 'Completed' -or (Test-Path $p.Runtime)){throw 'Positive cleanup failed.'};$d=Read-RepatoTaskStore $p.Store;$t=Find-RepatoTask $d $p.TaskId;if($t.PreAttemptCleanup.Status -ne 'Completed' -or $t.mayaTaraAttempt -or @($t.mayaTaraAttemptHistory).Count -ne 1 -or $t.mayaTaraAttemptHistory[0].AttemptId -ne $p.AttemptId){throw 'Historical cleanup evidence failed.'};foreach($id in 'unrelated-absent','unrelated-null','unrelated-legacy','unrelated-complete'){if(@($d.tasks|? taskId -ceq $id).Count -ne 1){throw 'Unrelated task shape was changed.'}};$again=Complete-MayaQaPreparedAttemptCleanup -StoreRoot $p.Store -TaskId $p.TaskId -WorkflowId $p.WorkflowId -RunId $p.RunId -AttemptId $p.AttemptId;if($again.Mode -ne 'AlreadyCompleted'){throw 'Idempotency failed.'}}finally{Remove-Item $p.Store -Recurse -Force -ErrorAction SilentlyContinue}
$cases=@('wrong-attempt','wrong-run','wrong-workflow','missing-attempt','ambiguous-attempt','execution','claim','native-request','request-sent','agent-accepted','revit','runner','outside-root','fixture','candidate','ownership','handoff-mismatch')
foreach($name in $cases){$c=New-Context $name;try{switch($name){'wrong-attempt'{Reject $c {param($x)$x.AttemptId='wrong'} $name};'wrong-run'{Reject $c {param($x)$x.RunId='wrong'} $name};'wrong-workflow'{Reject $c {param($x)$x.WorkflowId='wrong'} $name};'missing-attempt'{Reject $c {param($x)$d=Read-RepatoTaskStore $x.Store;$t=Find-RepatoTask $d $x.TaskId;$t.PSObject.Properties.Remove('mayaTaraAttempt');Write-RepatoJsonAtomic (Join-Path $x.Store 'tasks.json') $d} $name};'ambiguous-attempt'{Reject $c {param($x)$d=Read-RepatoTaskStore $x.Store;$t=Find-RepatoTask $d $x.TaskId;$t|Add-Member NoteProperty mayaTaraAttemptHistory ([object[]]@([pscustomobject]@{AttemptId=$x.AttemptId})) -Force;Write-RepatoJsonAtomic (Join-Path $x.Store 'tasks.json') $d} $name};'execution'{Reject $c {param($x)$d=Read-RepatoTaskStore $x.Store;$t=Find-RepatoTask $d $x.TaskId;$t|Add-Member NoteProperty mayaTaraExecution ([pscustomobject]@{}) -Force;Write-RepatoJsonAtomic (Join-Path $x.Store 'tasks.json') $d} $name};'claim'{Reject $c {param($x)$d=Read-RepatoTaskStore $x.Store;$t=Find-RepatoTask $d $x.TaskId;$t.mayaTaraAttempt|Add-Member NoteProperty ClaimId 'claim' -Force;Write-RepatoJsonAtomic (Join-Path $x.Store 'tasks.json') $d} $name};'native-request'{Reject $c {param($x)$d=Read-RepatoTaskStore $x.Store;$t=Find-RepatoTask $d $x.TaskId;$t.mayaTaraAttempt.RequestPath='x';Write-RepatoJsonAtomic (Join-Path $x.Store 'tasks.json') $d} $name};'request-sent'{Reject $c {param($x)$d=Read-RepatoTaskStore $x.Store;$t=Find-RepatoTask $d $x.TaskId;$t.mayaTaraAttempt|Add-Member NoteProperty NativeRequestSent $true -Force;Write-RepatoJsonAtomic (Join-Path $x.Store 'tasks.json') $d} $name};'agent-accepted'{Reject $c {param($x)$d=Read-RepatoTaskStore $x.Store;$t=Find-RepatoTask $d $x.TaskId;$t.mayaTaraAttempt|Add-Member NoteProperty LaunchAgentAccepted $true -Force;Write-RepatoJsonAtomic (Join-Path $x.Store 'tasks.json') $d} $name};'revit'{Reject $c {param($x)$d=Read-RepatoTaskStore $x.Store;$t=Find-RepatoTask $d $x.TaskId;$t.mayaTaraAttempt|Add-Member NoteProperty RevitLaunched $true -Force;Write-RepatoJsonAtomic (Join-Path $x.Store 'tasks.json') $d} $name};'runner'{Reject $c {param($x)$d=Read-RepatoTaskStore $x.Store;$t=Find-RepatoTask $d $x.TaskId;$t.mayaTaraAttempt|Add-Member NoteProperty QaRunnerStarted $true -Force;Write-RepatoJsonAtomic (Join-Path $x.Store 'tasks.json') $d} $name};'outside-root'{Reject $c {param($x)$d=Read-RepatoTaskStore $x.Store;$t=Find-RepatoTask $d $x.TaskId;$t.mayaTaraAttempt.RuntimeRoot=$x.Store;Write-RepatoJsonAtomic (Join-Path $x.Store 'tasks.json') $d} $name};'fixture'{Reject $c {param($x)$d=Read-RepatoTaskStore $x.Store;$t=Find-RepatoTask $d $x.TaskId;$t.mayaTaraAttempt.RuntimeRoot=(Split-Path $fixture -Parent);$t.mayaTaraQaPacket.ModelPath=$fixture;Write-RepatoJsonAtomic (Join-Path $x.Store 'tasks.json') $d} $name};'candidate'{Reject $c {param($x)$d=Read-RepatoTaskStore $x.Store;$t=Find-RepatoTask $d $x.TaskId;$t.mayaTaraAttempt.RuntimeRoot=$candidate;$t.mayaTaraQaPacket.ModelPath=$candidate;Write-RepatoJsonAtomic (Join-Path $x.Store 'tasks.json') $d} $name};'ownership'{Reject $c {param($x)$d=Read-RepatoTaskStore $x.Store;$t=Find-RepatoTask $d $x.TaskId;$other=[pscustomobject]@{taskId='other';mayaTaraAttempt=[pscustomobject]@{RuntimeRoot=$x.Runtime}};$d.tasks=[object[]]@($d.tasks)+$other;Write-RepatoJsonAtomic (Join-Path $x.Store 'tasks.json') $d} $name};'handoff-mismatch'{Reject $c {param($x)$d=Read-RepatoTaskStore $x.Store;$t=Find-RepatoTask $d $x.TaskId;$t.mayaTaraQaPacket.AttemptId='wrong';Write-RepatoJsonAtomic (Join-Path $x.Store 'tasks.json') $d} $name};'cas-shape'{Reject $c {param($x)$d=Read-RepatoTaskStore $x.Store;$t=Find-RepatoTask $d $x.TaskId;$t.revision=[long]$t.revision+1;Write-RepatoJsonAtomic (Join-Path $x.Store 'tasks.json') $d} $name}}}finally{Remove-Item $c.Store -Recurse -Force -ErrorAction SilentlyContinue}}
$source=Get-Content (Join-Path $PSScriptRoot 'Repato.MayaQaWorkflow.psm1') -Raw;if($source -notmatch 'Prepared-attempt cleanup compare-and-swap failed'){throw 'CAS guard was not present.'};foreach($p in $made){if(Test-Path $p){Remove-Item $p -Recurse -Force -ErrorAction SilentlyContinue}};[pscustomobject]@{PreparedAttemptCleanup='PASS';FocusedTestsPassed=29;FocusedTestsTotal=29;RealStoreTouched=$false;RealRuntimeRemoved=$false;ClaimCreated=$false;NativeRequestSent=$false;RevitLaunched=$false}|ConvertTo-Json -Compress
